//! `app calc`: 64-bit signed integer expression evaluator: one expression per input line.
//!
//! See the `calc` section of SPEC.md.
//!
//! Expressions are evaluated by an operator-precedence (shunting-yard) parser with explicit
//! stacks rather than recursive descent, so arbitrarily deep nesting such as `((((…))))` or
//! `----…1` cannot overflow the call stack.

use std::io::{self, BufRead, Write};

/// Entry point for `app calc`: reads all of `input` and writes the result to `output`.
///
/// `output` is already buffered and is flushed by the caller.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut evaluator = Evaluator::default();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        let expr = line.strip_suffix(b"\n").unwrap_or(&line);
        if expr.iter().all(|&b| is_blank(b)) {
            continue;
        }
        match evaluator.evaluate(expr) {
            Ok(value) => writeln!(output, "{value}")?,
            Err(_) => writeln!(output, "error")?,
        }
    }
}

/// Why an expression has no value. All kinds print as `error`; they are kept distinct for
/// clarity and testing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Error {
    Syntax,
    DivisionByZero,
    Overflow,
}

/// An operator waiting on the operator stack.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Op {
    Neg,
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    /// An open parenthesis: a barrier that reductions never cross.
    Open,
}

impl Op {
    fn binary(byte: u8) -> Option<Self> {
        Some(match byte {
            b'+' => Self::Add,
            b'-' => Self::Sub,
            b'*' => Self::Mul,
            b'/' => Self::Div,
            b'%' => Self::Rem,
            _ => return None,
        })
    }

    /// Binding strength; higher binds tighter. `Open` binds loosest so it is never reduced.
    fn precedence(self) -> u8 {
        match self {
            Self::Open => 0,
            Self::Add | Self::Sub => 1,
            Self::Mul | Self::Div | Self::Rem => 2,
            Self::Neg => 3,
        }
    }
}

/// What the parser expects next.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Expect {
    /// A number, `(`, or unary `-`.
    Operand,
    /// A binary operator, `)`, or the end of the line.
    Operator,
}

/// Evaluates expressions, reusing its stacks across calls to avoid per-line allocation.
#[derive(Debug, Default)]
struct Evaluator {
    values: Vec<i64>,
    ops: Vec<Op>,
}

impl Evaluator {
    fn evaluate(&mut self, expr: &[u8]) -> Result<i64, Error> {
        self.values.clear();
        self.ops.clear();

        let mut expect = Expect::Operand;
        let mut i = 0;
        while let Some(&byte) = expr.get(i) {
            i += 1;
            if is_blank(byte) {
                continue;
            }
            match expect {
                Expect::Operand => match byte {
                    b'-' => self.ops.push(Op::Neg),
                    b'(' => self.ops.push(Op::Open),
                    b'0'..=b'9' => {
                        let start = i - 1;
                        let end = expr[start..]
                            .iter()
                            .position(|b| !b.is_ascii_digit())
                            .map_or(expr.len(), |len| start + len);
                        self.values.push(parse_literal(&expr[start..end])?);
                        i = end;
                        expect = Expect::Operator;
                    }
                    _ => return Err(Error::Syntax),
                },
                Expect::Operator => {
                    if byte == b')' {
                        self.reduce_while(|_| true)?;
                        if self.ops.pop() != Some(Op::Open) {
                            return Err(Error::Syntax);
                        }
                    } else {
                        let op = Op::binary(byte).ok_or(Error::Syntax)?;
                        // Left associativity: reduce everything that binds at least as tightly.
                        self.reduce_while(|top| top.precedence() >= op.precedence())?;
                        self.ops.push(op);
                        expect = Expect::Operand;
                    }
                }
            }
        }

        if expect == Expect::Operand {
            return Err(Error::Syntax);
        }
        self.reduce_while(|_| true)?;
        match (self.ops.as_slice(), self.values.as_slice()) {
            ([], &[value]) => Ok(value),
            _ => Err(Error::Syntax),
        }
    }

    /// Applies stacked operators down to the nearest `Open` while `pred` holds for the top one.
    fn reduce_while(&mut self, pred: impl Fn(Op) -> bool) -> Result<(), Error> {
        while let Some(&op) = self.ops.last() {
            if op == Op::Open || !pred(op) {
                break;
            }
            self.ops.pop();
            self.apply(op)?;
        }
        Ok(())
    }

    fn apply(&mut self, op: Op) -> Result<(), Error> {
        let rhs = self.values.pop().ok_or(Error::Syntax)?;
        let result = if op == Op::Neg {
            rhs.checked_neg().ok_or(Error::Overflow)?
        } else {
            let lhs = self.values.pop().ok_or(Error::Syntax)?;
            binary(op, lhs, rhs)?
        };
        self.values.push(result);
        Ok(())
    }
}

fn binary(op: Op, lhs: i64, rhs: i64) -> Result<i64, Error> {
    if rhs == 0 && matches!(op, Op::Div | Op::Rem) {
        return Err(Error::DivisionByZero);
    }
    match op {
        Op::Add => lhs.checked_add(rhs),
        Op::Sub => lhs.checked_sub(rhs),
        Op::Mul => lhs.checked_mul(rhs),
        Op::Div => lhs.checked_div(rhs),
        // `i64::MIN % -1` is mathematically 0; only the quotient overflows.
        Op::Rem => Some(lhs.wrapping_rem(rhs)),
        Op::Neg | Op::Open => unreachable!("{op:?} is not a binary operator"),
    }
    .ok_or(Error::Overflow)
}

/// Parses a non-empty run of ASCII digits.
fn parse_literal(digits: &[u8]) -> Result<i64, Error> {
    digits.iter().try_fold(0i64, |acc, &d| {
        acc.checked_mul(10)
            .and_then(|acc| acc.checked_add(i64::from(d - b'0')))
            .ok_or(Error::Overflow)
    })
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(expr: &str) -> Result<i64, Error> {
        Evaluator::default().evaluate(expr.as_bytes())
    }

    fn run_str(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            run_str("1 + 2 * 3\n-7 / 2\n(1 + 2\n9223372036854775807 + 1\n"),
            "7\n-3\nerror\nerror\n"
        );
    }

    #[test]
    fn precedence_and_associativity() {
        assert_eq!(eval("(1 + 2) * 3"), Ok(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Ok(5));
        assert_eq!(eval("10 - 4 - 3"), Ok(3));
        assert_eq!(eval("100 / 10 / 5"), Ok(2));
        assert_eq!(eval("-2 * 3"), Ok(-6));
        assert_eq!(eval("- 2 - - 3"), Ok(1));
    }

    #[test]
    fn division_semantics() {
        assert_eq!(eval("-7 / 2"), Ok(-3));
        assert_eq!(eval("-7 % 3"), Ok(-1));
        assert_eq!(eval("7 % -3"), Ok(1));
        assert_eq!(eval("1 / 0"), Err(Error::DivisionByZero));
        assert_eq!(eval("1 % (2 - 2)"), Err(Error::DivisionByZero));
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807"), Ok(i64::MAX));
        assert_eq!(eval("9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("-9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("-9223372036854775807 - 1"), Ok(i64::MIN));
        assert_eq!(eval("-(-9223372036854775807 - 1)"), Err(Error::Overflow));
        assert_eq!(
            eval("(-9223372036854775807 - 1) / -1"),
            Err(Error::Overflow)
        );
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Ok(0));
        assert_eq!(eval("4611686018427387904 * 2"), Err(Error::Overflow));
        assert_eq!(eval("0000000000000000000000000000001"), Ok(1));
    }

    #[test]
    fn syntax_errors() {
        for expr in [
            "1 +", "abc", "()", "1 2", "+1", "(1", "1)", ")(", "1 + * 2", "-", "1 -", "2 (3)",
            "(1)(2)", "1\r", "1 ^ 2", "1 2 + 3",
        ] {
            assert_eq!(eval(expr), Err(Error::Syntax), "{expr:?}");
        }
    }

    #[test]
    fn blank_lines_and_missing_final_newline() {
        assert_eq!(run_str("\n  42  \n\t\n1+1"), "42\n2\n");
        assert_eq!(run_str(""), "");
    }

    #[test]
    fn deep_nesting_does_not_overflow_the_stack() {
        let depth = 1_000_000;
        let nested = format!("{}7{}", "(".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&nested), Ok(7));
        let negated = format!("{}7", "-".repeat(depth + 1));
        assert_eq!(eval(&negated), Ok(-7));
    }
}

//! `app lru`: LRU cache simulator: executes SET/GET/DEL/SIZE commands against a bounded cache.
//!
//! See the `lru` section of SPEC.md.
//!
//! The cache is a hash map from key to a slot in an arena of nodes; the nodes form an
//! intrusive doubly linked list ordered from most to least recently used. Every command is
//! O(1) expected time, and freed slots are recycled so the arena never exceeds `C + 1` nodes.

use std::collections::HashMap;
use std::io::{self, BufRead, Write};

/// Largest capacity accepted on the first line.
const MAX_CAPACITY: usize = 1_000_000;

/// Entry point for `app lru`: reads all of `input` and writes the result to `output`.
///
/// `output` is already buffered and is flushed by the caller.
///
/// Blank lines and lines that are not a well-formed command are ignored.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut line = Vec::new();
    if input.read_until(b'\n', &mut line)? == 0 {
        return Ok(());
    }
    let capacity = parse_capacity(trim_line_end(&line))?;
    let mut cache = LruCache::with_capacity(capacity);

    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        let Some(command) = Command::parse(trim_line_end(&line)) else {
            continue;
        };
        match command {
            Command::Set { key, value } => cache.set(key, value),
            Command::Get { key } => {
                let value = cache.get(key).unwrap_or(b"NULL");
                output.write_all(value)?;
                output.write_all(b"\n")?;
            }
            Command::Del { key } => {
                output.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
            }
            Command::Size => writeln!(output, "{}", cache.len())?,
        }
    }
}

/// Strips the line terminator (`\n`, tolerating a preceding `\r`).
fn trim_line_end(line: &[u8]) -> &[u8] {
    let line = line.strip_suffix(b"\n").unwrap_or(line);
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn parse_capacity(line: &[u8]) -> io::Result<usize> {
    std::str::from_utf8(line)
        .ok()
        .and_then(|text| text.trim().parse::<usize>().ok())
        .filter(|capacity| (1..=MAX_CAPACITY).contains(capacity))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "invalid capacity '{}': expected an integer in 1..={MAX_CAPACITY}",
                    String::from_utf8_lossy(line)
                ),
            )
        })
}

/// One parsed input line, borrowing its tokens from the line buffer.
#[derive(Debug, PartialEq, Eq)]
enum Command<'a> {
    Set { key: &'a [u8], value: &'a [u8] },
    Get { key: &'a [u8] },
    Del { key: &'a [u8] },
    Size,
}

impl<'a> Command<'a> {
    /// Parses a line without its terminator; returns `None` if it is not a valid command.
    fn parse(line: &'a [u8]) -> Option<Self> {
        let mut tokens = line.split(|&byte| byte == b' ');
        let name = tokens.next()?;
        let mut operand = || tokens.next().filter(|token| !token.is_empty());
        let command = match name {
            b"SET" => Command::Set {
                key: operand()?,
                value: operand()?,
            },
            b"GET" => Command::Get { key: operand()? },
            b"DEL" => Command::Del { key: operand()? },
            b"SIZE" => Command::Size,
            _ => return None,
        };
        // Trailing tokens make the line malformed.
        tokens.next().is_none().then_some(command)
    }
}

/// Index of a node in the arena.
type Slot = u32;

/// Sentinel link meaning "no node".
const NIL: Slot = Slot::MAX;

#[derive(Debug)]
struct Node {
    key: Box<[u8]>,
    value: Vec<u8>,
    /// Neighbour towards the most recently used end.
    prev: Slot,
    /// Neighbour towards the least recently used end.
    next: Slot,
}

/// A fixed-capacity map that evicts its least recently used key on overflow.
#[derive(Debug)]
struct LruCache {
    capacity: usize,
    index: HashMap<Box<[u8]>, Slot>,
    nodes: Vec<Node>,
    /// Slots of removed nodes, available for reuse.
    free: Vec<Slot>,
    /// Most recently used node.
    head: Slot,
    /// Least recently used node.
    tail: Slot,
}

impl LruCache {
    /// Creates an empty cache holding at most `capacity` keys.
    ///
    /// # Panics
    ///
    /// If `capacity` is zero or too large for the slot type.
    fn with_capacity(capacity: usize) -> Self {
        assert!(capacity > 0, "LRU capacity must be positive");
        assert!(
            capacity < NIL as usize,
            "LRU capacity {capacity} exceeds the slot range"
        );
        // Reserve lazily-bounded space: large capacities are often never filled.
        let initial = capacity.min(1 << 16) + 1;
        Self {
            capacity,
            index: HashMap::with_capacity(initial),
            nodes: Vec::with_capacity(initial),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    fn len(&self) -> usize {
        self.index.len()
    }

    /// Returns the value for `key`, marking it most recently used.
    fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let slot = *self.index.get(key)?;
        self.move_to_front(slot);
        Some(&self.node(slot).value)
    }

    /// Inserts or overwrites `key`, marking it most recently used and evicting the least
    /// recently used key if the cache overflows.
    fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&slot) = self.index.get(key) {
            let node = self.node_mut(slot);
            node.value.clear();
            node.value.extend_from_slice(value);
            self.move_to_front(slot);
            return;
        }

        let node = Node {
            key: key.into(),
            value: value.to_vec(),
            prev: NIL,
            next: NIL,
        };
        let slot = match self.free.pop() {
            Some(slot) => {
                *self.node_mut(slot) = node;
                slot
            }
            None => {
                let slot = Slot::try_from(self.nodes.len()).expect("arena exceeds slot range");
                self.nodes.push(node);
                slot
            }
        };
        self.index.insert(key.into(), slot);
        self.push_front(slot);

        if self.len() > self.capacity {
            self.evict();
        }
    }

    /// Removes `key`; returns whether it was present.
    fn remove(&mut self, key: &[u8]) -> bool {
        let Some(slot) = self.index.remove(key) else {
            return false;
        };
        self.unlink(slot);
        self.release(slot);
        true
    }

    /// Removes the least recently used key.
    fn evict(&mut self) {
        let slot = self.tail;
        debug_assert_ne!(slot, NIL, "evicting from an empty cache");
        self.unlink(slot);
        let key = std::mem::take(&mut self.node_mut(slot).key);
        self.index.remove(&key);
        self.release(slot);
    }

    /// Returns an unlinked slot to the free list, dropping its buffers.
    fn release(&mut self, slot: Slot) {
        let node = self.node_mut(slot);
        node.key = Box::default();
        node.value = Vec::new();
        self.free.push(slot);
    }

    fn move_to_front(&mut self, slot: Slot) {
        if self.head != slot {
            self.unlink(slot);
            self.push_front(slot);
        }
    }

    /// Links an unlinked node in as the most recently used.
    fn push_front(&mut self, slot: Slot) {
        let old_head = self.head;
        let node = self.node_mut(slot);
        node.prev = NIL;
        node.next = old_head;
        if old_head == NIL {
            self.tail = slot;
        } else {
            self.node_mut(old_head).prev = slot;
        }
        self.head = slot;
    }

    /// Detaches a linked node from the list, leaving its own links stale.
    fn unlink(&mut self, slot: Slot) {
        let Node { prev, next, .. } = *self.node(slot);
        if prev == NIL {
            self.head = next;
        } else {
            self.node_mut(prev).next = next;
        }
        if next == NIL {
            self.tail = prev;
        } else {
            self.node_mut(next).prev = prev;
        }
    }

    fn node(&self, slot: Slot) -> &Node {
        &self.nodes[slot as usize]
    }

    fn node_mut(&mut self, slot: Slot) -> &mut Node {
        &mut self.nodes[slot as usize]
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn simulate(input: &str) -> String {
        let mut output = Vec::new();
        run(input.as_bytes(), &mut output).expect("simulation failed");
        String::from_utf8(output).expect("output is not UTF-8")
    }

    #[test]
    fn spec_example() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(simulate(input), "1\nNULL\n2\n");
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let input = "2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c\n";
        assert_eq!(simulate(input), "9\nNULL\n3\n");
    }

    #[test]
    fn get_refreshes_recency() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET a\nGET b\nGET c";
        assert_eq!(simulate(input), "1\n1\nNULL\n3\n");
    }

    #[test]
    fn delete_reports_presence_and_frees_room() {
        let input = "2\nSET x 1\nSET y 2\nDEL x\nDEL x\nSET z 3\nSIZE\nGET y\nGET z\n";
        assert_eq!(simulate(input), "1\n0\n2\n2\n3\n");
    }

    #[test]
    fn capacity_one() {
        let input = "1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\nDEL b\nSIZE\nSET c 3\nGET c\n";
        assert_eq!(simulate(input), "NULL\n2\n1\n1\n0\n3\n");
    }

    #[test]
    fn last_line_without_newline_and_crlf() {
        assert_eq!(simulate("3\r\nSET a 1\r\nGET a"), "1\n");
    }

    #[test]
    fn empty_input_prints_nothing() {
        assert_eq!(simulate(""), "");
    }

    #[test]
    fn malformed_lines_are_ignored() {
        let input = "2\n\nFOO\nSET a\nGET\nSET a 1 2\nGET a b\nSIZE x\nSET a 1\nGET a\n";
        assert_eq!(simulate(input), "1\n");
    }

    #[test]
    fn invalid_capacity_is_an_error() {
        for input in ["0\n", "abc\n", "1000001\n"] {
            let error = run(input.as_bytes(), Vec::new()).unwrap_err();
            assert_eq!(error.kind(), io::ErrorKind::InvalidData, "input {input:?}");
        }
    }

    #[test]
    fn slots_are_reused() {
        let mut cache = LruCache::with_capacity(2);
        for round in 0..100u32 {
            let key = round.to_string();
            cache.set(key.as_bytes(), b"v");
            if round % 3 == 0 {
                assert!(cache.remove(key.as_bytes()));
            }
        }
        assert!(cache.len() <= 2);
        assert!(cache.nodes.len() <= 3);
    }

    #[test]
    fn matches_naive_model() {
        // Deterministic pseudo-random workload checked against an O(n) reference model.
        let mut state = 0x2545_f491_4f6c_dd1d_u64;
        let mut next = move || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        let capacity = 7;
        let mut cache = LruCache::with_capacity(capacity);
        let mut model: Vec<(Vec<u8>, Vec<u8>)> = Vec::new(); // most recent last
        for _ in 0..20_000 {
            let key = format!("k{}", next() % 20).into_bytes();
            match next() % 3 {
                0 => {
                    let value = format!("v{}", next() % 1000).into_bytes();
                    cache.set(&key, &value);
                    model.retain(|(k, _)| *k != key);
                    model.push((key, value));
                    if model.len() > capacity {
                        model.remove(0);
                    }
                }
                1 => {
                    let expected = model.iter().position(|(k, _)| *k == key).map(|at| {
                        let entry = model.remove(at);
                        model.push(entry);
                        model.last().unwrap().1.clone()
                    });
                    assert_eq!(cache.get(&key).map(<[u8]>::to_vec), expected);
                }
                _ => {
                    let at = model.iter().position(|(k, _)| *k == key);
                    if let Some(at) = at {
                        model.remove(at);
                    }
                    assert_eq!(cache.remove(&key), at.is_some());
                }
            }
            assert_eq!(cache.len(), model.len());
        }
    }
}

//! `app`: a suite of independent stdin/stdout tools selected by the first argument.
//!
//! Each subcommand lives in its own module and exposes a single entry point:
//!
//! ```ignore
//! pub fn run(input: impl BufRead, output: impl Write) -> io::Result<()>
//! ```
//!
//! `main` owns process concerns only: argument dispatch, locking and buffering
//! the standard streams, flushing, and mapping errors to an exit status.

mod calc;
mod lru;
mod wordfreq;

use std::env;
use std::io::{self, BufRead, BufWriter, Write};
use std::process::ExitCode;

type Entry = fn(&mut dyn BufRead, &mut dyn Write) -> io::Result<()>;

const SUBCOMMANDS: &[(&str, Entry)] = &[
    ("wordfreq", |i, o| wordfreq::run(i, o)),
    ("lru", |i, o| lru::run(i, o)),
    ("calc", |i, o| calc::run(i, o)),
];

fn usage() -> String {
    let names: Vec<&str> = SUBCOMMANDS.iter().map(|&(name, _)| name).collect();
    format!("usage: app <{}>", names.join("|"))
}

fn main() -> ExitCode {
    let mut args = env::args().skip(1);
    let (Some(command), None) = (args.next(), args.next()) else {
        eprintln!("{}", usage());
        return ExitCode::from(2);
    };
    let Some(&(_, entry)) = SUBCOMMANDS.iter().find(|&&(name, _)| name == command) else {
        eprintln!("app: unknown subcommand '{command}'\n{}", usage());
        return ExitCode::from(2);
    };

    let mut input = io::stdin().lock();
    let mut output = BufWriter::new(io::stdout().lock());
    match entry(&mut input, &mut output).and_then(|()| output.flush()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("app {command}: {err}");
            ExitCode::FAILURE
        }
    }
}

//! `app wordfreq`: Word frequencies: prints the 10 most frequent ASCII words of the input.
//!
//! See the `wordfreq` section of SPEC.md.

use std::cmp::Ordering;
use std::collections::HashMap;
use std::io::{self, BufRead, Write};

/// How many of the most frequent words are printed.
const TOP_N: usize = 10;

/// Entry point for `app wordfreq`: reads all of `input` and writes the result to `output`.
///
/// `output` is already buffered and is flushed by the caller.
pub fn run(input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let counts = count_words(input)?;
    for (word, count) in top_words(counts, TOP_N) {
        output.write_all(count.to_string().as_bytes())?;
        output.write_all(b" ")?;
        output.write_all(&word)?;
        output.write_all(b"\n")?;
    }
    Ok(())
}

/// Counts the lowercased words of `input`, streaming it chunk by chunk.
///
/// A word is a maximal run of ASCII letters; every other byte is a separator.
/// A word split across chunk boundaries is carried over in a pending buffer.
fn count_words(mut input: impl BufRead) -> io::Result<HashMap<Vec<u8>, u64>> {
    let mut counts = HashMap::new();
    let mut word = Vec::new();
    loop {
        let chunk = match input.fill_buf() {
            Ok([]) => break,
            Ok(chunk) => chunk,
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        };
        for &byte in chunk {
            if byte.is_ascii_alphabetic() {
                word.push(byte.to_ascii_lowercase());
            } else if !word.is_empty() {
                record(&mut counts, &word);
                word.clear();
            }
        }
        let len = chunk.len();
        input.consume(len);
    }
    if !word.is_empty() {
        record(&mut counts, &word);
    }
    Ok(counts)
}

/// Increments the count of `word`, allocating a key only for a word not seen before.
fn record(counts: &mut HashMap<Vec<u8>, u64>, word: &[u8]) {
    match counts.get_mut(word) {
        Some(count) => *count += 1,
        None => {
            counts.insert(word.to_vec(), 1);
        }
    }
}

/// Ranking order: count descending, then word ascending (byte order).
fn rank(a: &(Vec<u8>, u64), b: &(Vec<u8>, u64)) -> Ordering {
    b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0))
}

/// Returns the `n` highest-ranked `(word, count)` pairs, in ranking order.
fn top_words(counts: HashMap<Vec<u8>, u64>, n: usize) -> Vec<(Vec<u8>, u64)> {
    let mut entries: Vec<_> = counts.into_iter().collect();
    if entries.len() > n {
        if n == 0 {
            return Vec::new();
        }
        entries.select_nth_unstable_by(n - 1, rank);
        entries.truncate(n);
    }
    entries.sort_unstable_by(rank);
    entries
}

#[cfg(test)]
mod tests {
    use super::*;

    fn wordfreq(input: &[u8]) -> String {
        let mut out = Vec::new();
        run(input, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            wordfreq(b"The cat and the hat."),
            "2 the\n1 and\n1 cat\n1 hat\n"
        );
    }

    #[test]
    fn empty_and_wordless_input() {
        assert_eq!(wordfreq(b""), "");
        assert_eq!(wordfreq(b"123 _ ' \xff\xfe !"), "");
    }

    #[test]
    fn non_ascii_bytes_separate_words() {
        assert_eq!(wordfreq(b"ab\xc3\xa9cd AB"), "2 ab\n1 cd\n");
    }

    #[test]
    fn words_spanning_chunk_boundaries() {
        let reader = io::BufReader::with_capacity(3, &b"hello HELLO hello"[..]);
        let mut out = Vec::new();
        run(reader, &mut out).unwrap();
        assert_eq!(out, b"3 hello\n");
    }

    #[test]
    fn at_most_ten_lines_with_ties_by_word() {
        let input = "k j i h g f e d c b a a";
        assert_eq!(
            wordfreq(input.as_bytes()),
            "2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"
        );
    }
}
